   G("Molten Shower", ["Chaos Attunement", "Retreat III", "Execute II", "Multishot II", "Close Combat II"], L("Dano automático", "Automatic damage"), L("Concedida pela própria Brutus' Lead Sprinkler — cada maça dá uma cópia, então você roda duas com os mesmos supports.", "Granted by Brutus' Lead Sprinkler itself — each mace grants one copy, so you run two with the same supports."), "free"),
   G("Molten Blast", ["Rapid Attacks II", "Nova Projectiles I", "Salvo", "Poison III", "Magnified Area II"], L("Gera Glory", "Builds Glory"), L("Único botão manual do clear: alguns hits bastam para encher os 100 de Glory e ligar o Archon.", "The clear's only manual button: a few hits are enough to fill the 100 Glory and turn on the Archon."), "free"),
